oxy_webhelp_navlinks = {"ir_clean_recovery-d39536e57054":{"topics":[{"title":"Recovery paths","shortdesc":"<p class=\"shortdesc\">Comparison between roll forward and targeted rollback. Roll forward is recommended         when a clean rebuild is required, and targeted rollback is recommended when the attack is         contained and minimal disruption to the live environment is a priority.<\/p>","href":"identity_resilience\/ir_recovery_paths.html","attributes":{"data-id":"ir_recovery_paths"},"menu":{"hasChildren":false},"tocID":"ir_recovery_paths-d39536e57065","topics":[]},{"title":"Roll forward","shortdesc":"<p class=\"shortdesc\">Roll forward restores a compromised identity environment to a clean baseline         snapshot, then replays only legitimate changes from the compromise window into the restored         environment.<\/p>","href":"identity_resilience\/ir_roll_forward.html","attributes":{"data-id":"ir_roll_forward"},"menu":{"hasChildren":false},"tocID":"ir_roll_forward-d39536e57076","topics":[]},{"title":"Targeted rollback","shortdesc":"<p class=\"shortdesc\">Targeted rollback stays in the current live environment and reverts only the changes         you select, preserving all other changes from the same window.<\/p>","href":"identity_resilience\/ir_targeted_rollback.html","attributes":{"data-id":"ir_targeted_rollback"},"menu":{"hasChildren":false},"tocID":"ir_targeted_rollback-d39536e57087","topics":[]},{"title":"Change classifications in clean recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> assigns each change detected during clean recovery one of three         classifications based on signals from connected integrations and user-uploaded         files.<\/p>","href":"identity_resilience\/ir_change_classifications.html","attributes":{"data-id":"ir_change_classifications"},"menu":{"hasChildren":false},"tocID":"ir_change_classifications-d39536e57098","next":"ir_change_classifications-d39536e57098"},{"title":"Snapshot threat enrichment","shortdesc":"<p class=\"shortdesc\">Snapshot threat enrichment marks snapshots that fall within a confirmed compromise         window, helping you select a safe recovery point and avoid restoring from a compromised         state. For Active Directory, enrichment uses both Rubrik's internal Threat Monitoring scan         and identity threat integration alerts. For Microsoft Entra ID, enrichment uses identity         threat integration alerts.<\/p>","href":"identity_resilience\/ir_snapshot_threat_enrichment.html","attributes":{"data-id":"ir_snapshot_threat_enrichment"},"menu":{"hasChildren":false},"tocID":"ir_snapshot_threat_enrichment-d39536e57133","topics":[]},{"title":"Snapshot comparison","shortdesc":"<p class=\"shortdesc\">Snapshot comparison identifies every object that changed between the clean baseline         snapshot and the latest available snapshot, and attributes each change to the actor who made         it using the activity log.<\/p>","href":"identity_resilience\/ir_snapshot_comparison.html","attributes":{"data-id":"ir_snapshot_comparison"},"menu":{"hasChildren":false},"tocID":"ir_snapshot_comparison-d39536e57144","topics":[]},{"title":"Clean recovery for Active Directory","shortdesc":"<p class=\"shortdesc\">Clean recovery for Active Directory combines Active Directory Forest Recovery         with roll forward recovery to return the AD forest to a clean and current state         after a security breach.<\/p>","href":"identity_resilience\/ir_clean_recovery_ad.html","attributes":{"data-id":"ir_clean_recovery_ad"},"menu":{"hasChildren":false},"tocID":"ir_clean_recovery_ad-d39536e57155","next":"ir_clean_recovery_ad-d39536e57155"},{"title":"Clean recovery for Microsoft Entra ID","shortdesc":"<p class=\"shortdesc\">Clean recovery returns a compromised Microsoft Entra ID tenant to a known clean state         using one of two recovery types: roll forward or targeted rollback.<\/p>","href":"identity_resilience\/ir_clean_rec_entra_id.html","attributes":{"data-id":"ir_clean_rec_entra_id"},"menu":{"hasChildren":false},"tocID":"ir_clean_rec_entra_id-d39536e57199","next":"ir_clean_rec_entra_id-d39536e57199"}]}};